print(f"Total stories gathered: {len(all_stories)}")
assert len(all_stories) == 108, f"Expected 108, got {len(all_stories)}"

# Now format into final JSON structure
json_chapters = []
for num, title, syn, body, moral in all_stories:
    expo_html = f"""<div class='child-story-body' style='font-size:1.24rem; line-height:2.1; color:#f8fafc; font-family:"Mukta Malar", Georgia, serif;'>
<h3 style='color:#ffd700; margin-bottom:14px; font-size:1.45rem;'>கதை {num}: {title}</h3>
<p style='margin-bottom:18px;'>{body}</p>
</div>
<div style='background:rgba(250,204,21,0.12); border:1px solid #facc15; border-radius:14px; padding:16px 20px; margin-top:24px;'>
<strong style='color:#facc15; font-size:1.15rem;'>🌟 இக்கதை உணர்த்தும் நீதி:</strong> <span style='font-size:1.15rem; color:#ffffff;'>{moral}</span>
</div>"""

    json_chapters.append({
        "chapterNumber": num,
        "title": f"கதை {num}: {title}",
        "synopsis": syn,
        "exposition": expo_html
    })

kandha_json_path = "data/puranas/kandha-puranam.json"
with open(kandha_json_path, "r", encoding="utf-8") as f:
    doc = json.load(f)

doc['title'] = "கந்த புராணம் — 108 முழுமையான சிறார் பெருங்கதைக் களஞ்சியம் (Kandha Puranam)"
